import{_ as t,o as s,c as i,a5 as n}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"证据篇：变化要如何被看见","description":"建立从基线、即时表现、延迟保持到真实迁移的证据链，判断学习、AI 协作和人生行动是否真的改变。","frontmatter":{"title":"证据篇：变化要如何被看见","description":"建立从基线、即时表现、延迟保持到真实迁移的证据链，判断学习、AI 协作和人生行动是否真的改变。","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-3/5-evidence-and-transfer.md","filePath":"threads/part-3/5-evidence-and-transfer.md","lastUpdated":1788220800000}'),e={name:"threads/part-3/5-evidence-and-transfer.md"};function l(r,a,d,p,h,o){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="证据篇-变化要如何被看见" tabindex="-1">证据篇：变化要如何被看见 <a class="header-anchor" href="#证据篇-变化要如何被看见" aria-label="Permalink to &quot;证据篇：变化要如何被看见&quot;">​</a></h1><p>人很容易把熟悉感当成能力，把完成打卡当成进步，把一段顺利的对话当成已经学会。真正困难的不是收集更多数字，而是知道哪些痕迹足以回答眼前的问题。需要把一次任务完整记录下来时，可以直接使用<a href="./../../templates/evidence-chain">证据链模板</a>。</p><p>我写“证据”，不是想把生活改造成一张冷冰冰的仪表盘。相反，证据让我们少一点自我欺骗，也少一点无根据的自责：它告诉我们哪里确实变好了，哪里只是暂时顺手，哪里需要换一种方法，哪里应该停止继续投入。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>证据必须回到具体任务、条件和时间，而不是脱离场景的分数；</li><li>用基线、即时表现、延迟保持和迁移样本组成一条证据链；</li><li>把 AI 辅助下的表现与独立表现分开，记录交接时谁承担判断；</li><li>失败、返工和不适用的条件同样是证据；</li><li>生活中的变化不能都量化，但可以用更诚实的观察和边界来记录；</li><li>每七天只复查一个主问题，避免用更多记录代替真正的行动。</li></ul><h2 id="_1-证据不是成绩单" tabindex="-1">1. 证据不是成绩单 <a class="header-anchor" href="#_1-证据不是成绩单" aria-label="Permalink to &quot;1. 证据不是成绩单&quot;">​</a></h2><p>成绩单回答的是“在某一套规则下得了多少分”。证据回答的是“在什么条件下，我完成了什么，别人能否复查，下一次能否重做”。两者有时重叠，但从来不是一回事。</p><p>收藏了十篇文章，不能证明你能解释其中一个概念；和 AI 共同写出一段代码，不能证明你能在没有聊天记录时维护它；连续早起七天，也不能自动证明你的生活更有秩序。它们最多是线索，必须被放回任务中检查。</p><p>一个有用的证据至少要能回答四个问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>需要写清什么</th><th>缺少时会发生什么</th></tr></thead><tbody><tr><td>能追溯吗？</td><td>样本、来源、版本和日期在哪里</td><td>结果只能靠记忆复述</td></tr><tr><td>有条件吗？</td><td>主题、听众、时间、工具和限制是什么</td><td>不同条件被误当成同一水平</td></tr><tr><td>能比较吗？</td><td>前后两次是否保留了相近任务</td><td>变化无法归因或复核</td></tr><tr><td>能迁移吗？</td><td>换主题、对象或场景后还能完成吗</td><td>熟练只停留在练习原题</td></tr></tbody></table><p>证据不是为了把人排队，而是为了让下一次选择少一点盲目。</p><h2 id="_2-保存四个时间点" tabindex="-1">2. 保存四个时间点 <a class="header-anchor" href="#_2-保存四个时间点" aria-label="Permalink to &quot;2. 保存四个时间点&quot;">​</a></h2><p>同一个任务，最好保存四种状态。它们不要求每次都很长，却要明确区分“谁在什么时候提供了什么帮助”。</p><table tabindex="0"><thead><tr><th>时间点</th><th>目的</th><th>示例</th></tr></thead><tbody><tr><td><strong>基线</strong></td><td>在集中训练或工具介入前，知道自己真正能做什么</td><td>不查稿解释一个熟悉工作流程</td></tr><tr><td><strong>即时表现</strong></td><td>在练习或反馈刚结束后，观察当前能否完成</td><td>看过示范并修订后重新录音</td></tr><tr><td><strong>延迟保持</strong></td><td>隔一段时间、没有刚刚的提示时再做一次</td><td>七天后换一段材料重做同类任务</td></tr><tr><td><strong>迁移样本</strong></td><td>改变主题、听众、媒介或约束，检查能力是否离开原题</td><td>把内部说明改成给客户的简短说明</td></tr></tbody></table><p>如果只保存即时表现，最容易高估自己；如果只保存最终成品，又会忘记自己如何从不会走到会。四个时间点放在一起，才更接近一条可解释的变化轨迹。</p><h2 id="_3-三种结果不要混为一谈" tabindex="-1">3. 三种结果不要混为一谈 <a class="header-anchor" href="#_3-三种结果不要混为一谈" aria-label="Permalink to &quot;3. 三种结果不要混为一谈&quot;">​</a></h2><p>学习中常见三类结果：<strong>做得出来</strong>、<strong>过几天还记得</strong>、<strong>换个地方仍然能用</strong>。它们彼此相关，却需要不同的检查。</p><ul><li><strong>表现</strong>：今天能否完成任务？看清楚错误、时间和外部帮助；</li><li><strong>保持</strong>：一段时间后还能否完成？去掉刚刚的提示，保留相近难度；</li><li><strong>迁移</strong>：任务换了外壳还能否完成？改变主题、对象、顺序或压力条件。</li></ul><p>例如，你在 AI 帮助下写出一封英文邮件，说明即时表现可能不错；隔天不看原稿独立写一封相近邮件，才能观察保持；真正面对一位语气不同的客户仍能澄清问题，才开始接近迁移。不要用第一种结果替第二种和第三种盖章。</p><h2 id="_4-ai-介入时-记录人工门" tabindex="-1">4. AI 介入时，记录人工门 <a class="header-anchor" href="#_4-ai-介入时-记录人工门" aria-label="Permalink to &quot;4. AI 介入时，记录人工门&quot;">​</a></h2><p>AI 会改变速度，也会改变任务的性质。使用工具时，不要只记录“用了什么模型”，还要记录哪些判断仍由人完成：</p><table tabindex="0"><thead><tr><th>条件</th><th>人需要完成什么</th><th>证据重点</th></tr></thead><tbody><tr><td><strong>独立版</strong></td><td>不看 AI，先完成自己的第一版</td><td>基线、错误和卡住的位置</td></tr><tr><td><strong>辅助版</strong></td><td>允许 AI 提问、解释、比较或反馈</td><td>提示、来源、修改理由和返工</td></tr><tr><td><strong>交接版</strong></td><td>关闭聊天后向别人解释、维护或继续完成</td><td>关键决定、权限、测试和责任人</td></tr></tbody></table><p>如果 AI 直接产出最终答案，你应该额外做一次“撤掉工具后的复测”。不会解释的正确答案，不能算作已经拥有的能力；不能交接的自动化，也不能算作可以放心运行的系统。</p><p>这也是为什么本书反复要求保存<a href="./../../templates/ai-task-brief">AI 任务简报</a>、<a href="./../../templates/artifact-brief">作品简报与交付卡</a>和<a href="./../../templates/learning-state">学习状态</a>：它们不是文书工作，而是把人工门和责任边界留在记录里。</p><h2 id="_5-把失败和返工写进证据" tabindex="-1">5. 把失败和返工写进证据 <a class="header-anchor" href="#_5-把失败和返工写进证据" aria-label="Permalink to &quot;5. 把失败和返工写进证据&quot;">​</a></h2><p>只展示顺利的版本，会让方法看起来比现实简单。失败至少提供三种信息：哪个条件没有成立，哪个假设被推翻，下一次应该减少哪一种风险。</p><p>记录失败时，不要只写“没做好”。可以写成：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">任务与条件：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我原本以为：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">实际发生了：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最早出现的错误：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">返工花了什么成本：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次只改变哪一个变量：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">什么结果会让我停止继续投入：</span></span></code></pre></div><p>返工次数本身不是能力指标。一次及时的返工可能保护了用户和关系；反复修理一个不值得做的任务，则可能是在逃避更重要的决定。证据的价值不在于让记录看起来漂亮，而在于让代价能够参与下一次选择。</p><h2 id="_6-不把生活做成仪表盘" tabindex="-1">6. 不把生活做成仪表盘 <a class="header-anchor" href="#_6-不把生活做成仪表盘" aria-label="Permalink to &quot;6. 不把生活做成仪表盘&quot;">​</a></h2><p>有些变化适合计数：完成了几次交付、延迟复测的正确率、一个测试是否通过。有些变化不适合被压成单一分数：是否更敢求助、是否减少了对别人的伤害、是否终于能在疲惫时停下来。</p><p>对后者，可以记录更接近事实的观察：</p><ul><li>我在什么场景下比以前更早发现自己已经超载？</li><li>我是否向受影响的人说明了边界，而不是突然消失？</li><li>一次冲突之后，我做了什么修复，结果如何？</li><li>我是否因为保留休息而减少了一次高风险决定？</li><li>哪些变化只有自己知道，哪些变化已经被别人观察到？</li></ul><p>这些问题没有统一答案，也不要求把关系和身体变成 KPI。它们只是帮助我们把“我好像变了”拆成可以尊重隐私、承认不确定性的叙述。</p><h2 id="_7-用证据决定下一步-而不是决定自己的价值" tabindex="-1">7. 用证据决定下一步，而不是决定自己的价值 <a class="header-anchor" href="#_7-用证据决定下一步-而不是决定自己的价值" aria-label="Permalink to &quot;7. 用证据决定下一步，而不是决定自己的价值&quot;">​</a></h2><p>证据可以说明一项方法在某个条件下是否有效，不能说明一个人值不值得被爱、是否有资格重新开始。一次失败的录音、一项没有通过的测试或一周没有完成计划，都不能成为人格判决。</p><p>每周复查时，按这个顺序问：</p><ol><li>事实是什么？只写看得见、听得见、能回到文件或来源的部分；</li><li>哪个解释最有用？同时保留至少一个可能的反例；</li><li>下一次要改变哪一个变量？不要同时更换材料、工具、时间和目标；</li><li>需要什么支持或边界？包括同伴、专业人士、授权和暂停条件；</li><li>什么时候复测？让日期、场景和完成标准先于情绪决定。</li></ol><p>如果证据不够，不要急着给自己打分。缩小问题、保存更好的基线，往往比制造一个精确但虚假的结论更诚实。</p><h2 id="_8-一页证据链" tabindex="-1">8. 一页证据链 <a class="header-anchor" href="#_8-一页证据链" aria-label="Permalink to &quot;8. 一页证据链&quot;">​</a></h2><p>可以把一次学习或生活行动压缩成下面这一页：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Evidence Chain — YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">主问题：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实场景与受影响的人：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">完成标准：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">基线样本（条件 / 位置 / 日期）：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">即时表现（做了什么 / 得到什么帮助）：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">延迟保持（何时 / 去掉什么提示）：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">迁移样本（改变了什么条件）：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最重要的错误或失败：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">证据支持的结论：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">仍然只是推测的部分：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">隐私、权限、健康或关系边界：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次只改变的变量：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">复测日期与停止条件：</span></span></code></pre></div><p>这一页可以链接到<a href="./../../templates/weekly-review">每周复盘模板</a>和<a href="./../../templates/90-day-cycle">九十日行动总表</a>。当周期结束时，把它与最初的样本并排放置；不要只保留总结句，也保留曾经做错的版本。</p><h2 id="_9-七天证据审计" tabindex="-1">9. 七天证据审计 <a class="header-anchor" href="#_9-七天证据审计" aria-label="Permalink to &quot;9. 七天证据审计&quot;">​</a></h2><p>接下来七天，每天只检查一件事：</p><ol><li><strong>第 1 天</strong>：保存一个未经 AI 帮助的基线；</li><li><strong>第 2 天</strong>：写清任务条件和完成标准；</li><li><strong>第 3 天</strong>：完成一次辅助练习，记录 AI 的具体作用；</li><li><strong>第 4 天</strong>：关闭工具，独立重做同一任务的一小部分；</li><li><strong>第 5 天</strong>：找一个真实的人、测试或来源提出反例；</li><li><strong>第 6 天</strong>：换一个主题或听众，做一次迁移尝试；</li><li><strong>第 7 天</strong>：比较四个时间点，只决定下一周期改变的一个变量。</li></ol><p>七天之后，你可能发现自己没有“进步很多”，但会更清楚进步发生在哪里、还没有发生在哪里。这种清楚本身就是一种能力，因为它让下一步不必依赖兴奋或羞耻。</p><p>证据不是终点，而是下一项责任的入口。准备把方法带进技术与企业交付时，进入<a href="./2-ai-development-and-resource-layer">AI 开发与资源层创业</a>，让结果接受用户、成本、故障和交接检验；准备把一项能力交给完整周期时，进入<a href="./../part-5/90-day-plan">行动篇：九十天，把生活交还给自己</a>；如果某个概念仍然含混，先回到<a href="./../../reference/glossary">术语与方法索引</a>，不要带着不清楚的定义继续加码。</p><h2 id="结语-让变化能够被诚实地看见" tabindex="-1">结语：让变化能够被诚实地看见 <a class="header-anchor" href="#结语-让变化能够被诚实地看见" aria-label="Permalink to &quot;结语：让变化能够被诚实地看见&quot;">​</a></h2><p>人生里有许多重要的变化没有掌声：一次没有发出的伤人消息，一次及时的求助，一段终于完成的道歉，一份在疲惫中仍然保留了边界的交付。它们未必适合做成图表，却值得被记住。</p><p>我希望证据最终带来的，不是对自己的监控，而是一种温和的可信度：我知道自己曾经在哪里，我知道今天做到了什么，也知道哪些结论还不能急着写下。拥有这份可信度之后，我们既不需要把偶然的顺利夸大成天赋，也不必把一次失败扩大成命运。</p><p>变化不是因为被记录才发生。记录只是让我们在变化发生之后，有机会认出它，并把它带到下一段生活里。</p>`,52)])])}const E=t(e,[["render",l]]);export{c as __pageData,E as default};
